  if hit:
   sty=hit.group(1);sty=re.sub(r'grid-column:[^;"\n]*(?:;|$)','',sty);sty=re.sub(r'grid-row:[^;"\n]*(?:;|$)','',sty)
   t=t[:hit.start(1)]+'grid-column:1 / span 12; grid-row:1 / span 6; '+sty+t[hit.end(1):]
  write(f,t)
